css=f''':root{{{decl}
--background:var(--color-grey-50);--surface:var(--color-grey-00);--foreground:var(--color-grey-900);--foreground-secondary:var(--color-grey-600);--secondary:var(--color-grey-100);--radius-8:8px;--radius-14:14px;--radius-28:28px}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth;scroll-padding-top:80px}}body{{margin:0;background:var(--background);color:var(--foreground);font:15px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}a{{color:inherit;text-underline-offset:4px}}.container{{max-width:1320px;margin:auto;padding:0 22px}}.hero{{padding-top:54px;padding-bottom:36px;background:radial-gradient(ellipse at 80% 0,var(--color-yellow-200),transparent 60%),var(--surface)}}.eyebrow{{font:11px ui-monospace,monospace;letter-spacing:.1em;color:var(--foreground-secondary)}}h1{{font-size:clamp(36px,5vw,64px);line-height:1.08;letter-spacing:-.055em;margin:24px 0}}h1 span{{color:var(--foreground-secondary)}}.lead{{max-width:900px;font-size:20px;line-height:1.6}}h2{{font-size:30px;line-height:1.2;letter-spacing:-.035em;margin:0}}h3{{font-size:19px;line-height:1.4;margin:10px 0}}.section{{padding-top:40px}}.heading{{padding:24px 0 12px}}.heading small{{font-size:10px;letter-spacing:.1em;color:var(--foreground-secondary)}}.links{{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}}.link{{padding:10px 15px;background:var(--secondary);border-radius:var(--radius-8);font-size:13px;text-decoration:none}}.link.main{{background:var(--foreground);color:var(--surface)}}nav{{position:sticky;top:0;z-index:2;background:var(--surface);box-shadow:0 8px 20px color-mix(in srgb,var(--foreground) 4%,transparent)}}.nav{{display:flex;gap:18px;overflow:auto;padding-block:14px;white-space:nowrap;font-size:12px}}.decision{{padding:24px;background:var(--color-green-50);color:var(--color-green-900);border-radius:var(--radius-28);margin-top:24px}}.decision p{{margin-bottom:0}}.three{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}}.two{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}}.card{{padding:24px;background:var(--surface);border-radius:var(--radius-28);min-width:0}}.card p{{font-size:14px;color:var(--foreground-secondary)}}.phone-image{{width:195px;max-width:100%;height:auto;display:block;margin:20px auto;border-radius:var(--radius-14)}}.capture-pair{{display:flex;justify-content:center;gap:18px;align-items:flex-start;flex-wrap:wrap}}.capture-pair figure{{margin:0}}.capture-pair img{{width:250px;max-width:100%;border-radius:var(--radius-28)}}figcaption{{font-size:11px;color:var(--foreground-secondary);max-width:270px;margin-top:8px}}.tag{{display:inline-block;font-size:10px;line-height:16px;border-radius:var(--radius-8);padding:4px 8px;background:var(--secondary)}}.new{{color:var(--color-red-800);background:var(--color-red-50)}}.green{{color:var(--color-green-800);background:var(--color-green-50)}}.table-wrap{{overflow:auto;background:var(--surface);border-radius:var(--radius-28)}}table{{border-collapse:collapse;width:100%;min-width:850px;text-align:left}}th{{background:var(--secondary);color:var(--foreground-secondary);font-size:11px;letter-spacing:.05em;text-transform:uppercase;padding:16px}}td{{font-size:13px;vertical-align:top;padding:20px 16px}}tr:nth-child(even){{background:color-mix(in srgb,var(--secondary) 45%,var(--surface))}}.muted{{color:var(--foreground-secondary)}}.small{{font-size:12px}}.money-line{{font-size:32px;letter-spacing:-.04em;font-weight:650}}.principle{{font-size:24px;line-height:1.4;letter-spacing:-.03em}}.evidence-grid{{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}}.evidence-grid figure{{margin:0;min-width:0}}.evidence-grid img{{width:100%;height:auto;border-radius:var(--radius-14)}}.evidence-grid p{{font-size:11px}}.source details{{margin:12px 0;background:var(--surface);padding:16px;border-radius:var(--radius-14)}}.source pre{{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}}footer{{padding:40px 22px;background:var(--surface);margin-top:40px;font-size:12px;color:var(--foreground-secondary)}}.indicator{{width:139px;height:5px;background:var(--foreground);border-radius:var(--radius-8);margin:24px auto 0}}.swatches{{display:flex;gap:8px;margin:16px 0}}.swatches span{{width:40px;height:40px;border-radius:var(--radius-8)}}.swatches span:nth-child(1){{background:var(--color-yellow-200)}}.swatches span:nth-child(2){{background:var(--color-grey-900)}}.swatches span:nth-child(3){{background:var(--color-grey-100)}}.swatches span:nth-child(4){{background:var(--color-blue-100)}}.swatches span:nth-child(5){{background:var(--color-green-100)}}@media(max-width:850px){{.three,.two{{grid-template-columns:1fr}}.evidence-grid{{grid-template-columns:repeat(2,1fr)}}.hero{{padding-top:32px}}.lead{{font-size:17px}}}}@media print{{nav,.links{{display:none}}.section,.card,tr{{break-inside:avoid}}table{{min-width:0}}td{{font-size:10px;padding:10px}}}}
'''
