phases=p['phases'];phaseCards=''.join(f'<article class="card"><span class="eyebrow">{label}</span><h3>{e(phases[k]["user"])}</h3><p>{e(phases[k]["journey"])}</p><p><strong>Điều kiện:</strong> {e(phases[k]["dependency"])}</p><p><strong>Độ chắc:</strong> {e(phases[k]["certainty"])}</p></article>' for k,label in [('current','HIỆN TẠI'),('feb2027','ĐẾN 02/2027'),('end2027','KHUNG CUỐI 2027')])
comparisons=[('Tata Neu','Điểm chung nối nhiều thương hiệu.','VinClub cần thể hiện nơi dùng điểm, không chỉ số dư.'),('Grab','Tác vụ và trạng thái đơn hỗ trợ nhu cầu thường ngày.','Dịch vụ phải có đích và kết quả, không chỉ icon mở danh mục.'),('Marriott Bonvoy','Quyền lợi gắn với hạng và hành trình sử dụng.','Tách quyền lợi đã có với nội dung chào mời.'),('ShopBack','Chuyển khách sang đối tác và ghi nhận kết quả.','Click chưa phải mua; rõ nơi giao dịch và điều kiện ghi nhận.'),('Weixin / WeChat','Giao tiếp nối dịch vụ.','Không để Chat thành phụ thuộc ra mắt khi chưa có SDK.')]
