slideCSS=f'''*{{box-sizing:border-box}}body{{margin:0;background:{bg};color:{fg};font-family:Arial,sans-serif}}.slide{{width:1280px;height:720px;margin:24px auto;padding:40px 50px;position:relative;background:{white};display:flex;gap:44px;overflow:hidden}}.slide-copy{{width:820px}}small{{font-size:11px;letter-spacing:.12em;color:{green}}}h1{{font-size:42px;line-height:1.12;letter-spacing:-.04em;margin:30px 0 20px}}h2{{font-size:24px;line-height:1.4;color:{muted};font-weight:400;margin:18px 0 28px}}ul{{font-size:21px;line-height:1.55;padding-left:24px}}li{{margin:14px 0}}.slide>img{{width:260px;height:563px;object-fit:contain;margin-top:28px;border-radius:20px}}footer{{position:absolute;left:50px;bottom:20px;font-size:11px;color:{muted}}}.appendix{{display:block}}.appendix h1{{font-size:32px;margin:18px 0}}.appendix>img{{display:block;max-width:100%;width:auto;height:500px;margin:15px auto;object-fit:contain}}.appendix>img[src*=desktop]{{width:100%;height:500px}}.source-slide{{display:block}}.source-slide ul{{font-size:17px;overflow-wrap:anywhere}}.controls{{position:fixed;right:12px;bottom:12px;background:{fg};color:{white};padding:10px 15px;z-index:5;font-size:12px}}.controls a{{color:inherit}}body.present .slide{{display:none;margin:0 auto}}body.present .slide.active{{display:flex}}body.present .slide.appendix,body.present .slide.source-slide{{display:none}}body.present .slide.active.appendix,body.present .slide.active.source-slide{{display:block}}@media print{{@page{{size:13.333in 7.5in;margin:0}}.slide{{margin:0;break-after:page}}.controls{{display:none}}}}'''
(R/'slides.html').write_text('<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VinClub V5 · Slide quyết định & Final UI</title><style>'+slideCSS+'</style></head><body>'+''.join(htmlSlides)+'<div class="controls">← → đổi slide · F trình chiếu · <a href="index.html">Report</a> · <a href="/vinclub-decision-v5?scenario=spend">Final UI</a></div><script>const ss=[...document.querySelectorAll(".slide")];let n=0;function render(){ss.forEach((s,i)=>s.classList.toggle("active",i===n))}document.addEventListener("keydown",e=>{if(e.key==="ArrowRight")n=Math.min(ss.length-1,n+1);if(e.key==="ArrowLeft")n=Math.max(0,n-1);if(e.key.toLowerCase()==="f")document.body.classList.toggle("present");render()});render()</script></body></html>')
(R/'delivery.json').write_text(json.dumps({'version':'V5','roles':['UX','Business','Product','Visual','CEO'],'prototype':'/vinclub-decision-v5','uiScenarios':['daily','spend','experience'],'report':'index.html','slides':'slides.html','pptx':'vinclub-v5.pptx','pdf':'vinclub-v5.pdf','slideCount':len(prs.slides),'humanUT':'NOT_RUN','automatedQA':{'passed':h['passed'],'total':h['total'],'pass':h['pass']},'previousVersions':'preserved'},ensure_ascii=False,indent=2))
print('Built report, slide HTML and PPTX',len(prs.slides),'slides')
